import json
V=8363
files = {1:'kick',2:'snare',3:'hatc',4:'hato',5:'clap',6:'bass',7:'sub',
         8:'saw',9:'arp',10:'pad',11:'pluck',12:'tick',13:'fx'}
names = {1:'kick',2:'snare',3:'hat closed',4:'hat open',5:'clap',6:'fm bass',
         7:'sub bass',8:'saw lead',9:'square arp',10:'pad',11:'pluck',12:'tick',13:'noise fx'}
vols  = {1:64,2:58,3:46,4:42,5:52,6:64,7:64,8:54,9:46,10:48,11:58,12:40,13:50}
loops = {8:(int(0.012*V),1023), 9:(int(0.006*V),1023), 10:(int(0.05*V),2046)}

calls = [{"name":"module_new","arguments":{"channels":12,"name":"0xDEADBEEF - silicon sunrise"}}]
for i in range(1,14):
    calls.append({"name":"sample_load","arguments":{"path":f"/workspace/samples/{files[i]}.wav","instrument":i,"sample":0}})
    meta = {"instrument":i,"sample":0,"name":names[i],"volume":vols[i],"panning":128}
    if i in loops:
        meta["loop_start"], meta["loop_length"] = loops[i]; meta["flags"]=1
    calls.append({"name":"sample_set","arguments":meta})
    calls.append({"name":"instrument_set","arguments":{"instrument":i,"name":names[i]}})

pat = json.load(open('scripts/patterns_batch.json'))
calls += pat
calls += [{"name":"module_save","arguments":{"path":"/workspace/submission/tune.xm","format":"xm"}},
          {"name":"module_render","arguments":{"path":"/workspace/preview.wav","rate":44100,"loops":2}}]
json.dump(calls, open('scripts/full_batch2.json','w'))
print(len(calls), "calls")
EOF
